  bubble: { life: 1.9, up: 0.5, drag: 0.99, g: -0.35, size: 1, spread: 0.5, spin: 0 },
  star: { life: 1.1, up: 1.4, drag: 0.97, g: -0.6, size: 1, spread: 1.6, spin: 4 },
};

