html,
body,
#root {
  margin: 0;
  height: 100%;
  overflow: hidden;
}

body {
  font-family: ui-rounded, "SF Pro Rounded", system-ui, -apple-system, "Segoe UI", sans-serif;
  color: #3d2b4f;
  background: #bfe9ff;
  -webkit-font-smoothing: antialiased;
  user-select: none;
}

.app {
  position: relative;
  height: 100vh;
  width: 100vw;
}

.stage {
  position: absolute;
  inset: 0;
  width: 100% !important;
  height: 100% !important;
  display: block;
}

/* Top bar */
.topbar {
  position: absolute;
  top: 18px;
  left: 22px;
  right: 22px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  pointer-events: none;
  z-index: 2;
}

.topbar h1 {
  margin: 0;
  font-size: 22px;
  font-weight: 800;
  letter-spacing: -0.01em;
  background: rgba(255, 255, 255, 0.7);
  padding: 8px 16px;
  border-radius: 999px;
  box-shadow: 0 6px 20px rgba(80, 60, 140, 0.12);
}

.mood {
  padding: 8px 14px;
  border-radius: 999px;
  font-weight: 700;
  font-size: 14px;
  background: #fff;
  box-shadow: 0 6px 20px rgba(80, 60, 140, 0.12);
}
.mood-happy { color: #d6336c; }
.mood-hungry { color: #d9480f; }
.mood-sad { color: #5c7cfa; }
.mood-tired { color: #7048e8; }
.mood-dirty { color: #8a6f5a; }
.mood-sleeping { color: #364fc7; background: #dbe4ff; }

/* Speech bubble */
.bubble {
  position: absolute;
  top: 15%;
  left: 50%;
  transform: translateX(-50%);
  max-width: min(440px, 80vw);
  padding: 12px 18px;
  border-radius: 20px;
  background: #ffffff;
  font-weight: 700;
  font-size: 17px;
  text-align: center;
  box-shadow: 0 10px 30px rgba(80, 60, 140, 0.18);
  pointer-events: none;
  z-index: 2;
  animation: pop 0.35s cubic-bezier(0.2, 1.4, 0.4, 1);
}
.bubble::after {
  content: "";
  position: absolute;
  left: 50%;
  bottom: -9px;
  width: 18px;
  height: 18px;
  background: #fff;
  transform: translateX(-50%) rotate(45deg);
}

@keyframes pop {
  from { opacity: 0; transform: translate(-50%, 8px) scale(0.85); }
  to { opacity: 1; transform: translate(-50%, 0) scale(1); }
}

/* Stats panel */
.panel {
  position: absolute;
  top: 88px;
  left: 22px;
  width: 210px;
  padding: 16px;
  border-radius: 22px;
  background: rgba(255, 255, 255, 0.72);
  backdrop-filter: blur(10px);
  box-shadow: 0 10px 30px rgba(80, 60, 140, 0.12);
  z-index: 2;
}

.bar + .bar {
  margin-top: 12px;
}

.bar-head {
  display: flex;
  justify-content: space-between;
  font-size: 13px;
  font-weight: 700;
  margin-bottom: 5px;
}

.bar-track {
  height: 10px;
  border-radius: 999px;
  background: rgba(61, 43, 79, 0.12);
  overflow: hidden;
}

.bar-fill {
  height: 100%;
  border-radius: 999px;
  transition: width 0.4s ease;
}

.hint {
  margin: 14px 0 0;
  font-size: 12px;
  line-height: 1.4;
  opacity: 0.7;
}

/* Action bar */
.actions {
  position: absolute;
  left: 50%;
  bottom: 22px;
  transform: translateX(-50%);
  display: flex;
  gap: 14px;
  padding: 10px;
  border-radius: 26px;
  background: rgba(255, 255, 255, 0.78);
  backdrop-filter: blur(10px);
  box-shadow: 0 12px 34px rgba(80, 60, 140, 0.16);
  z-index: 2;
  max-width: calc(100vw - 24px);
  flex-wrap: wrap;
  justify-content: center;
}

.group {
  display: flex;
  gap: 8px;
}

.group + .group {
  padding-left: 14px;
  border-left: 2px solid rgba(61, 43, 79, 0.1);
}

.action {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  min-width: 70px;
  padding: 8px 10px;
  border: 0;
  border-radius: 18px;
  background: #fff;
  color: inherit;
  font: inherit;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
  box-shadow: inset 0 -3px 0 rgba(61, 43, 79, 0.08);
  transition: transform 0.12s ease, background 0.2s ease;
}

.action:hover:not(:disabled) {
  transform: translateY(-3px);
  background: #fff7fb;
}

.action:active:not(:disabled) {
  transform: translateY(1px) scale(0.97);
}

.action:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.action .icon {
  font-size: 26px;
  line-height: 1;
}

@media (max-width: 760px) {
  .panel {
    top: auto;
    bottom: 230px;
    left: 12px;
    right: 12px;
    width: auto;
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 0 14px;
  }
  .bar + .bar { margin-top: 0; }
  .hint { display: none; }
  .actions {
    bottom: 12px;
    width: calc(100vw - 24px);
  }
  .group + .group {
    padding-left: 0;
    border-left: 0;
  }
}

