  justify-content: space-between;
  font-size: 13px;
  font-weight: 700;
  margin-bottom: 5px;
}

.bar-track {
  height: 10px;
  border-radius: 999px;
  background: rgba(61, 43, 79, 0.12);
  overflow: hidden;
}

.bar-fill {
  height: 100%;
  border-radius: 999px;
  transition: width 0.4s ease;
}

.hint {
  margin: 14px 0 0;
  font-size: 12px;
  line-height: 1.4;
  opacity: 0.7;
}

/* Action bar */
.actions {
  position: absolute;
  left: 50%;
  bottom: 22px;
  transform: translateX(-50%);
  display: flex;
  gap: 14px;
  padding: 10px;
  border-radius: 26px;
  background: rgba(255, 255, 255, 0.78);
  backdrop-filter: blur(10px);
  box-shadow: 0 12px 34px rgba(80, 60, 140, 0.16);
  z-index: 2;
  max-width: calc(100vw - 24px);
  flex-wrap: wrap;
  justify-content: center;
}

.group {
  display: flex;
  gap: 8px;
}

.group + .group {
  padding-left: 14px;
  border-left: 2px solid rgba(61, 43, 79, 0.1);
}

.action {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  min-width: 70px;
  padding: 8px 10px;
  border: 0;
  border-radius: 18px;
  background: #fff;
  color: inherit;
  font: inherit;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
  box-shadow: inset 0 -3px 0 rgba(61, 43, 79, 0.08);
  transition: transform 0.12s ease, background 0.2s ease;
}

.action:hover:not(:disabled) {
  transform: translateY(-3px);
  background: #fff7fb;
}

.action:active:not(:disabled) {
  transform: translateY(1px) scale(0.97);
}

.action:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.action .icon {
  font-size: 26px;
  line-height: 1;
}

@media (max-width: 760px) {
  .panel {
    top: auto;
    bottom: 230px;
    left: 12px;
    right: 12px;
    width: auto;
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 0 14px;
  }
  .bar + .bar { margin-top: 0; }
  .hint { display: none; }
  .actions {
    bottom: 12px;
    width: calc(100vw - 24px);
  }
  .group + .group {
    padding-left: 0;
    border-left: 0;
  }
}

